CREATE TABLE `hizmetler` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT 'Hizmet tekil kimligi (PK)',
  `ad` varchar(100) NOT NULL COMMENT 'Hizmetin vitrin adi',
  `aciklama` text COMMENT 'Hizmet icerigi ve detaylari',
  `varsayilan_fiyat` decimal(10,2) NOT NULL COMMENT 'Mevcut guncel satis fiyati',
  `onceki_fiyat` decimal(10,2) DEFAULT NULL COMMENT 'Bir onceki satis fiyati',
  `insert_tarihi` datetime DEFAULT CURRENT_TIMESTAMP COMMENT 'Hizmetin sisteme eklenme tarihi',
  `guncelleme_tarihi` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT 'Fiyat veya detayin son degisim tarihi',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Musterilere sunulan bakim ve onarim hizmetlerinin fiyat listesi.';
