INSERT INTO `hizmetler` VALUES (1,'Standart Periyodik Bakım','Motor yağı, yağ filtresi, hava filtresi, polen filtresi değişimi ve sıvı kontrolleri.',4500.00,4500.01,'2026-03-25 15:06:53','2026-04-03 19:07:59'),(2,'Kışlık Bakım Paketi','Antifriz ölçümü ve değişimi, akü testi, kışlık silecek değişimi ve ısıtma sistemi kontrolü.',2500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(3,'Yazlık Bakım Paketi','Klima gazı kontrolü, radyatör temizliği, polen filtresi yenilemesi.',2800.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(4,'Ağır Bakım (Triger Seti)','Triger kayışı/zinciri, devirdaim pompası, V kayışı ve gergi bilyası değişimi.',18000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(5,'Motor Yağı ve Filtre Değişimi','Orijinal spesifikasyonlara uygun motor yağı ve yağ filtresi değişimi.',2000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(6,'Antifriz Değişimi','Soğutma sistemindeki eski suyun boşaltılıp yeni organik antifriz konulması.',1200.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(7,'Fren Hidroliği Değişimi','Fren hidrolik sıvısının (DOT4/DOT5) makine ile tamamen yenilenmesi.',1500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(8,'Direksiyon Hidroliği Değişimi','Hidrolik direksiyon sıvısının yenilenmesi ve havasının alınması.',1000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(9,'Cam Suyu ve Silecek Lastiği Değişimi','Ön ve arka silecek lastiklerinin değişimi, antifrizli cam suyu eklenmesi.',600.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(10,'Ekspertiz ve Check-Up','Kaporta, boya, motor ve mekanik durumun 101 nokta kontrolü ile raporlanması.',4000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(11,'Ön Fren Balata Değişimi','Ön aks fren balatalarının değişimi, disk yüzey kontrolü ve kaliper yağlaması.',2500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(12,'Arka Fren Balata Değişimi','Arka aks fren balatalarının değişimi ve el freni mekanizması ayarı.',2200.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(13,'Ön Fren Disk Değişimi (Çift)','Çizilmiş, incelmiş veya eğilmiş ön fren disklerinin yenisiyle değiştirilmesi.',6500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(14,'Arka Fren Disk Değişimi (Çift)','Arka fren disklerinin yenisiyle değiştirilmesi.',5500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(15,'Fren Kaliper Revizyonu','Sıkışan fren kaliperlerinin sökülüp tamir takımı ile yenilenmesi.',3000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(16,'Fren Merkezi Değişimi','Fren ana merkezinin arızalanması durumunda yenisiyle değiştirilmesi.',4500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(17,'Fren Hortumu Değişimi','Çatlamış veya hasar görmüş esnek fren hortumlarının değişimi.',1200.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(18,'ABS Sensörü Değişimi','Arıza veren tekerlek hız (ABS) sensörünün tespiti ve değişimi.',2500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(19,'ABS Beyni Tamiri','Arızalı ABS modülünün sökülerek elektronik tamirinin yapılması.',12000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(20,'El Freni Teli Değişimi','Kopan veya sıkışan el freni telinin yenilenmesi.',1800.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(21,'Buji Takımı Değişimi (Benzinli)','4 adet iridyum veya platinium ateşleme bujisinin değişimi.',2500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(22,'Kızdırma Bujisi Değişimi (Dizel)','Dizel motor ön ısıtma (kızdırma) bujilerinin takım halinde değişimi.',3500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(23,'Ateşleme Bobini Değişimi','Tekleyen veya arıza lambası yakan ateşleme bobininin yenilenmesi.',4500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(24,'Dizel Partikül Filtresi (DPF) Temizliği','Tıkalı partikül filtresinin özel makine ile temizlenmesi ve rejenerasyonu.',6000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(25,'EGR Valfi Temizliği / İptali','Kurum bağlamış EGR valfinin sökülerek temizlenmesi veya yazılımsal çözümü.',3500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(26,'Enjektör Bakımı ve Testi','Dizel/Benzin enjektörlerinin sökülüp cihazda test ve ultrasonik temizliğinin yapılması.',5000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(27,'Motor Takozu (Kulağı) Değişimi','Kabin içine titreşim veren kopmuş motor takozunun değişimi.',3500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(28,'Turbo Revizyonu','Yağ kaçıran veya ses yapan turbonun sökülüp kartuş değişimi ve revizyonu.',15000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(29,'Silindir Kapak Contası Değişimi','Hararet sonucu yanan contanın değişimi, kapak taşlama ve sızdırmazlık testi.',25000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(30,'Termostat Değişimi','Açık veya kapalı kalan termostatın yenisiyle değişimi ve su havasının alınması.',3000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(31,'Radyatör Değişimi','Su kaçıran veya tıkanan motor soğutma radyatörünün yenilenmesi.',6000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(32,'Su Pompası (Devirdaim) Değişimi','Su sızdıran veya ses yapan devirdaim pompasının değişimi.',4500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(33,'Motor Yağ Kaçağı Onarımı','Karter, külbütör veya krank keçesindeki yağ kaçaklarının giderilmesi.',5000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(34,'Katalitik Konvertör Temizliği','Tıkanmış katalizörün özel kimyasallarla açılarak emisyonun düşürülmesi.',4500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(35,'Boğaz Kelebeği Temizliği','Rölanti dalgalanmasına yol açan boğaz kelebeğinin temizlenip adaptasyon yapılması.',1500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(36,'Baskı Balata (Debriyaj) Seti Değişimi','Manuel araçlarda debriyaj seti, bilya değişimi ve şanzıman yağı ilavesi.',15000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(37,'Otomatik Şanzıman Yağı Değişimi','Tam otomatik şanzıman yağının makine ile tam kapasite değişimi ve filtre yenilemesi.',8500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(38,'DSG / EDC Kavrama Değişimi','Çift kavramalı şanzımanların kavrama setinin değişimi ve yazılım adaptasyonu.',35000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(39,'Şanzıman Beyni (Mekatronik) Tamiri','Vites geçiş sorunu yaratan mekatronik ünitesinin veya tüpünün onarımı.',25000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(40,'Aks Lalesi ve Körük Değişimi','Dönüşlerde ses yapan aks kafasının veya yırtık aks körüğünün değişimi.',2500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(41,'Ön Amortisör Değişimi (Çift)','Patlamış veya işlevini yitirmiş ön amortisörlerin çift olarak değişimi.',7000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(42,'Arka Amortisör Değişimi (Çift)','Arka süspansiyon amortisörlerinin değişimi.',5500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(43,'Z Rot (Askı Rotu) Değişimi','Çukurlarda lokurtu yapan Z rotların çift taraflı değişimi.',1500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(44,'Rotil ve Rot Başı Değişimi','Direksiyon boşluğuna sebep olan rotil ve rot başlarının yenilenmesi.',2500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(45,'Salıncak (Tabla) Değişimi','Burçları kopmuş veya eğilmiş salıncakların komple değişimi.',4500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(46,'Tekerlek Rulmanı (Porya) Değişimi','Hızlandıkça uğultu yapan tekerlek bilyasının presle sökülüp değişimi.',3500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(47,'Helezon Yayı Değişimi','Kırık, paslı veya sarkmış süspansiyon yaylarının çift olarak değişimi.',4000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(48,'Direksiyon Kutusu Revizyonu','Yağ kaçıran veya boşluk yapan kremayer direksiyon kutusunun tamiri.',12000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(49,'Bilgisayarlı Rot Balans Ayarı','Ön takım onarımı sonrası 4 tekerlek lazerli rot ayarı ve sök-tak balans.',1200.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(50,'Amortisör Takozu Değişimi','Direksiyonu çevirirken gıcırtı yapan amortisör üst takoz ve bilyasının değişimi.',2000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(51,'Akü Değişimi (72 Ah Standart)','Ömrünü tamamlamış akünün sökülmesi, yeni akü montajı ve şarj dinamosu ölçümü.',4000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(52,'Şarj Dinamosu (Alternatör) Tamiri','Akü şarj etmeyen dinamonun kömür, konjektör veya diyot tablosunun değişimi.',4500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(53,'Marş Dinamosu Tamiri','Basmayan marş motorunun sökülüp otomatiği ve kömürlerinin yenilenmesi.',4000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(54,'Klima Gazı Dolumu','Klima gazının (R134a) makine ile vakumlanıp tam gramajında basılması ve yağlanması.',1500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(55,'Klima Kompresör Tamiri','Kavrama yapmayan veya ses yapan klima kompresörünün revizyonu.',8500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(56,'Kalorifer Peteği Temizliği','Göğüs sökülmeden özel makine ve ilaçla tıkalı kalorifer peteğinin temizlenmesi.',2000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(57,'Far Ampulü / Xenon Değişimi','Patlak kısa/uzun far ampullerinin veya Xenon/LED beyinlerinin değişimi.',1200.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(58,'Far Temizliği ve Parlatma','Sararmış ve matlaşmış polikarbon far camlarının zımpara ve kloroform buharı ile parlatılması.',1200.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(59,'Sigorta ve Tesisat Onarımı','Oksitlenmiş tesisat kablolarının, rölelerin ve atan sigortaların tespiti/onarımı.',2500.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53'),(60,'Araç Beyin (ECU) Yazılım Güncellemesi','Motor veya şanzıman beyninin fabrika çıkışlı en güncel yazılımla güncellenmesi.',3000.00,NULL,'2026-03-25 15:06:53','2026-03-25 15:06:53');
